#!/usr/bin/env node
/**
 * The vibator binary.
 *
 * @packageDocumentation
 */
import { main } from "./cli/index.ts";

main(process.argv.slice(2)).then(
  (code) => {
    process.exitCode = code;
  },
  (error: unknown) => {
    process.stderr.write(
      `${error instanceof Error ? error.message : String(error)}\n`,
    );
    process.exitCode = 1;
  },
);

/**
 * The public surface of the vibator framework: the `vibator` namespace, the
 * rule definition surface, the configuration types and loader, and the engine
 * for running vibator programmatically.
 *
 * @packageDocumentation
 */

export * from "./configuration/index.ts";
export * from "./engine/index.ts";
export * from "./namespace/index.ts";
export * from "./rules/index.ts";

/**
 * The `vibator` command line: parse arguments, dispatch to the run command or a
 * subcommand.
 *
 * @packageDocumentation
 */
import { createRequire } from "node:module";
import { parseArgs } from "node:util";
import { run as runEngine } from "../engine/run.ts";
import { explain, init, list, skills } from "./commands/index.ts";
import { json, pretty, type Reporter, sarif } from "./reporters/index.ts";
import { spinner } from "./spinner.ts";

/**
 * The options the default command accepts.
 */
interface RunOptions {
  /** Runs each rule's `fix` and rechecks. */
  write?: boolean;
  /** Runs only these rule ids. */
  only?: string[];
  /** Loads configuration from a path instead of `.vibator.json`. */
  config?: string;
  /** Chooses the output format. Defaults to `pretty`. */
  reporter?: "pretty" | "json" | "sarif";
  /** Scopes the run to files staged for commit. */
  staged?: boolean;
  /** Scopes the run to uncommitted changes. */
  changed?: boolean;
  /** Scopes the run to changes since a ref. */
  since?: string;
  /** Draws the spinner while rules run. Defaults to `true`. */
  progress?: boolean;
}

/** The reporters selectable with `--reporter`. */
const reporters: Record<string, Reporter> = { pretty, json, sarif };

/**
 * Returns the vibator version from its package.json.
 *
 * @returns The version string.
 */
function version(): string {
  const manifest = createRequire(import.meta.url)("../../package.json") as {
    version: string;
  };
  return manifest.version;
}

/**
 * Runs the default command: run the engine, render with the chosen reporter,
 * and print.
 *
 * @param options - The run options.
 * @returns The process exit code.
 */
async function runCommand(options: RunOptions): Promise<number> {
  const result = await runEngine({
    config: options.config,
    only: options.only,
    write: options.write,
    staged: options.staged,
    changed: options.changed,
    since: options.since,
    onProgress: options.progress === false ? undefined : spinner(),
  });
  const reporter = reporters[options.reporter ?? "pretty"] ?? pretty;
  process.stdout.write(`${reporter(result.findings)}\n`);
  return result.exitCode;
}

/** Prints the command-line usage. */
function printUsage(): void {
  process.stdout.write(
    "Usage: vibator [options]\n" +
      "       vibator <list|explain|init|skills>\n\n" +
      "Options: --write --only <ids> --config <path>\n" +
      "         --reporter <pretty|json|sarif> --staged --changed --since <ref>\n" +
      "         --no-progress --help --version\n",
  );
}

/**
 * Parses the arguments and dispatches to the run command or a subcommand.
 *
 * @param argv - The command-line arguments after the binary.
 * @returns The process exit code.
 */
// biome-ignore lint/complexity/noExcessiveLinesPerFunction: argument parsing and dispatch read as one unit
export async function main(argv: string[]): Promise<number> {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: true,
    allowNegative: true,
    options: {
      write: { type: "boolean" },
      only: { type: "string" },
      config: { type: "string" },
      reporter: { type: "string" },
      staged: { type: "boolean" },
      changed: { type: "boolean" },
      since: { type: "string" },
      progress: { type: "boolean" },
      install: { type: "boolean" },
      help: { type: "boolean" },
      version: { type: "boolean" },
    },
  });

  if (values.help) {
    printUsage();
    return 0;
  }
  if (values.version) {
    process.stdout.write(`${version()}\n`);
    return 0;
  }

  switch (positionals[0]) {
    case "list":
      process.stdout.write(`${await list()}\n`);
      return 0;
    case "explain":
      process.stdout.write(`${await explain(positionals[1] ?? "")}\n`);
      return 0;
    case "init":
      process.stdout.write(`${init()}\n`);
      return 0;
    case "skills":
      process.stdout.write(`${skills(values.install ?? false)}\n`);
      return 0;
    case undefined:
      return runCommand({
        write: values.write,
        only: values.only?.split(","),
        config: values.config,
        reporter: values.reporter as RunOptions["reporter"],
        staged: values.staged,
        changed: values.changed,
        since: values.since,
        progress: values.progress,
      });
    default:
      process.stderr.write(`Unknown command: ${positionals[0]}\n`);
      return 1;
  }
}

/**
 * The `.vibator.json` configuration file and its loader.
 *
 * @packageDocumentation
 */
import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { z } from "zod";
import { module } from "../namespace/module/index.ts";
import { requireRoot } from "../namespace/runtime.ts";
import type { Severity } from "../rules/index.ts";

/**
 * The override one rule accepts.
 */
export interface RuleConfig {
  /** The severity applied to this rule. */
  severity?: Severity;
  /** The rule's options, validated by the rule's own schema. */
  options?: object;
}

/**
 * The `.vibator.json` configuration file. It is optional and overrides the
 * default configuration.
 */
export interface Config {
  /** The path or URL of the schema that validates this file. */
  $schema?: string;
  /** Paths or package names of base configs to inherit, applied in order. */
  extends?: string[];
  /**
   * Paths or package names of plugin modules: modules outside `.vibator/` that
   * add namespaces to `vibator`, register rules, or both.
   */
  plugins?: string[];
  /** Directory names to skip during file discovery, replacing the built-in defaults. */
  exclude?: string[];
  /**
   * Per-rule overrides, keyed by rule id. An entry is a {@link Severity} for the
   * severity shorthand, or a {@link RuleConfig}.
   */
  rules?: Record<string, Severity | RuleConfig>;
}

const severitySchema = z.enum(["error", "warn", "off"]);

const ruleConfigSchema = z.strictObject({
  severity: severitySchema.optional(),
  options: z.record(z.string(), z.unknown()).optional(),
});

/** The schema that validates a `.vibator.json`, emitted to `schema.json`. */
export const configSchema = z.strictObject({
  $schema: z.string().optional(),
  extends: z.array(z.string()).optional(),
  plugins: z.array(z.string()).optional(),
  exclude: z.array(z.string()).optional(),
  rules: z
    .record(z.string(), z.union([severitySchema, ruleConfigSchema]))
    .optional(),
});

/**
 * Turns a rule entry into its object form.
 *
 * @param entry - A severity shorthand or a rule config.
 * @returns The rule config.
 */
function ruleConfig(entry: Severity | RuleConfig): RuleConfig {
  return typeof entry === "string" ? { severity: entry } : entry;
}

/**
 * Merges two entries for one rule: the severity of the later one wins, and
 * options merge by key.
 *
 * @param base - The inherited entry.
 * @param own - The entry that overrides it.
 * @returns The merged entry.
 */
function mergeRule(
  base: Severity | RuleConfig,
  own: Severity | RuleConfig,
): RuleConfig {
  const from = ruleConfig(base);
  const to = ruleConfig(own);
  const merged: RuleConfig = { ...from, ...to };
  if (from.options !== undefined && to.options !== undefined) {
    merged.options = { ...from.options, ...to.options };
  }
  return merged;
}

/**
 * Merges two plugin lists: the inherited plugins first, then the own, each once.
 *
 * @param base - The inherited plugins.
 * @param own - The config's own plugins.
 * @returns The merged list, or `undefined` when neither config sets plugins.
 */
function mergePlugins(base?: string[], own?: string[]): string[] | undefined {
  if (base === undefined && own === undefined) return undefined;
  return [...new Set([...(base ?? []), ...(own ?? [])])];
}

/**
 * Merges two rule maps by id, merging the entries of a rule both set.
 *
 * @param base - The inherited rules.
 * @param own - The config's own rules.
 * @returns The merged rules, or `undefined` when neither config sets rules.
 */
function mergeRules(
  base?: Config["rules"],
  own?: Config["rules"],
): Config["rules"] {
  if (base === undefined) return own;
  const rules = { ...base };
  for (const [id, entry] of Object.entries(own ?? {})) {
    const inherited = rules[id];
    rules[id] = inherited === undefined ? entry : mergeRule(inherited, entry);
  }
  return rules;
}

/**
 * Merges a config onto an inherited one. Plugins add up, once each; `exclude`
 * is replaced; rules merge by id. The `$schema` field is never inherited.
 *
 * @param base - The inherited config.
 * @param own - The config that overrides it.
 * @returns The merged config, without `extends`.
 */
function mergeConfig(base: Config, own: Config): Config {
  const merged: Config = {
    $schema: own.$schema,
    plugins: mergePlugins(base.plugins, own.plugins),
    exclude: own.exclude ?? base.exclude,
    rules: mergeRules(base.rules, own.rules),
  };
  for (const key of Object.keys(merged) as (keyof Config)[]) {
    if (merged[key] === undefined) delete merged[key];
  }
  return merged;
}

/**
 * Reads a config file and resolves its `extends` chain into one config. The
 * plugins of a base resolve from the base file, so they come out absolute.
 *
 * @param file - The absolute path of the config file.
 * @param chain - The config files being read above this one.
 * @returns The resolved config.
 * @throws When a config extends itself through the chain.
 */
function resolveConfig(file: string, chain: string[]): Config {
  if (chain.includes(file)) {
    throw new Error(`Circular extends: ${[...chain, file].join(" -> ")}`);
  }
  const { extends: bases, ...own } = configSchema.parse(
    JSON.parse(readFileSync(file, "utf8")),
  );
  let inherited: Config = {};
  for (const specifier of bases ?? []) {
    const baseFile = module.resolve(specifier, file);
    const base = resolveConfig(baseFile, [...chain, file]);
    if (base.plugins !== undefined) {
      base.plugins = base.plugins.map((plugin) =>
        module.resolve(plugin, baseFile),
      );
    }
    inherited = mergeConfig(inherited, base);
  }
  return bases === undefined ? own : mergeConfig(inherited, own);
}

/**
 * Loads the configuration, validates it against the schema, and resolves its
 * `extends` chain.
 *
 * @remarks Reads `.vibator.json` from the project root when no path is given.
 * @param path - The path to load, when the file lives elsewhere.
 * @returns The parsed configuration, or an empty config when the file is absent.
 */
export function load(path?: string): Config {
  const target = path ?? join(requireRoot(), ".vibator.json");
  if (!existsSync(target)) return {};
  return resolveConfig(resolve(target), []);
}

/**
 * The engine: run vibator programmatically.
 *
 * @packageDocumentation
 */
export type { Finding } from "./finding.ts";
export { loadRules } from "./load-rules.ts";
export {
  type ProgressEvent,
  type RunInput,
  type RunResult,
  run,
} from "./run.ts";

/**
 * The `vibator` namespace: the data access layer a rule reads from.
 *
 * @packageDocumentation
 */
import { git } from "./git/index.ts";
import { glob } from "./glob/index.ts";
import { ignore } from "./ignore/index.ts";
import { json } from "./json/index.ts";
import { module } from "./module/index.ts";
import { pkg } from "./package/index.ts";
import { project } from "./project/index.ts";
import { shell } from "./shell/index.ts";
import { text } from "./text/index.ts";
import { ts } from "./ts/index.ts";

export type { StatusEntry } from "./git/index.ts";
export type { PackageManifest } from "./package/index.ts";
export type { File, FileSet, Folder, FolderSet } from "./project/index.ts";
export type { ShellOptions, ShellResult } from "./shell/index.ts";
export type { Hit, Line, Match, Position } from "./text/index.ts";
export type { Ast, NodeCursor, Program } from "./ts/index.ts";

/**
 * The type of the `vibator` object. A plugin that adds a namespace declares it
 * here with `declare module "vibator" { interface Vibator { ... } }`.
 */
export interface Vibator {
  /** Navigate the files and folders in this project, and write to them. */
  project: typeof project;
  /** Parse and manipulate TypeScript files. */
  ts: typeof ts;
  /** Parse JSON files. */
  json: typeof json;
  /** Parse and manipulate files as plain text. */
  text: typeof text;
  /** Check ignore markers for a rule at line, node, or file level. */
  ignore: typeof ignore;
  /** Gateway to git functionality. */
  git: typeof git;
  /** Gateway to the shell. */
  shell: typeof shell;
  /** Parse and manage `package.json` files. */
  package: typeof pkg;
  /** Resolve module specifiers to files. */
  module: typeof module;
  /** Match paths against globs. */
  glob: typeof glob;
}

/**
 * The base vibator framework namespace.
 */
export const vibator: Vibator = {
  /** Navigate the files and folders in this project, and write to them. */
  project,
  /** Parse and manipulate TypeScript files. */
  ts,
  /** Parse JSON files. */
  json,
  /** Parse and manipulate files as plain text. */
  text,
  /** Check ignore markers for a rule at line, node, or file level. */
  ignore,
  /** Gateway to git functionality. */
  git,
  /** Gateway to the shell. */
  shell,
  /** Parse and manage `package.json` files. */
  package: pkg,
  /** Resolve module specifiers to files. */
  module,
  /** Match paths against globs. */
  glob,
};

/**
 * Adds a namespace to the `vibator` object, so every rule reads it as
 * `vibator.<name>`. A plugin calls it when its module is imported.
 *
 * @param name - The property name on `vibator`.
 * @param value - The namespace.
 * @returns The same namespace.
 * @throws When `vibator` already has a namespace with that name.
 */
export function defineNamespace<Value extends object>(
  name: string,
  value: Value,
): Value {
  if (Object.hasOwn(vibator, name)) {
    throw new Error(`Duplicate namespace: ${name}`);
  }
  Object.defineProperty(vibator, name, {
    value,
    enumerable: true,
    configurable: true,
  });
  return value;
}

/**
 * The rule definition surface: the function that declares a rule, the shape of
 * a rule, and the types a rule returns.
 *
 * @packageDocumentation
 */
export { defineRule, type Rule } from "./define-rule.ts";
export type { Diagnostic } from "./diagnostic.ts";
export type { Report } from "./report.ts";
export type { Severity } from "./severity.ts";

/**
 * Test helpers for rule authors, exported as `vibator/testing`.
 *
 * @packageDocumentation
 */
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import type { Finding } from "../engine/finding.ts";
import { run } from "../engine/run.ts";
import type { Rule } from "../rules/define-rule.ts";

/**
 * The project a rule runs against in a test.
 */
export interface RuleFixture {
  /** The files of the project, keyed by root-relative path. */
  files?: Record<string, string>;
  /** The options passed to the rule, as `.vibator.json` would pass them. */
  options?: object;
}

/**
 * Writes the fixture files and the rule's options into a project folder.
 *
 * @param dir - The absolute project folder.
 * @param ruleId - The id of the rule the options belong to.
 * @param fixture - The files and options.
 */
function writeFixture(dir: string, ruleId: string, fixture: RuleFixture): void {
  for (const [path, content] of Object.entries(fixture.files ?? {})) {
    const absolute = join(dir, path);
    mkdirSync(dirname(absolute), { recursive: true });
    writeFileSync(absolute, content);
  }
  if (fixture.options) {
    const config = { rules: { [ruleId]: { options: fixture.options } } };
    writeFileSync(join(dir, ".vibator.json"), JSON.stringify(config));
  }
}

/**
 * Runs one rule against a temporary project and returns its findings. The
 * findings carry root-relative paths and no snippet or guideline, so a test
 * can compare them whole.
 *
 * @param rule - The rule to run. It must be defined with `defineRule`.
 * @param fixture - The project files and the rule options.
 * @returns The findings the rule produced.
 */
export async function runRule<Options>(
  rule: Rule<Options>,
  fixture: RuleFixture = {},
): Promise<Finding[]> {
  const dir = mkdtempSync(join(tmpdir(), "vibator-rule-"));
  try {
    writeFixture(dir, rule.id, fixture);
    const { findings } = await run({ root: dir, only: [rule.id] });
    return findings.map(({ snippet, docs, ...finding }) => finding);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/**
 * The informational and setup subcommands.
 *
 * @packageDocumentation
 */
import {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { type Config, load } from "../../configuration/index.ts";
import { loadRules } from "../../engine/load-rules.ts";
import { module } from "../../namespace/module/index.ts";
import { setRoot } from "../../namespace/runtime.ts";
import type { AnyRule } from "../../rules/define-rule.ts";
import type { Severity } from "../../rules/index.ts";

/**
 * Loads the rules and configuration for an informational command.
 *
 * @param root - The absolute project root.
 * @returns The registered rules and the loaded configuration.
 */
async function loadedRules(
  root: string,
): Promise<{ rules: AnyRule[]; config: Config }> {
  setRoot(root);
  const config = load();
  return { rules: await loadRules(config), config };
}

/**
 * The severity a rule runs at, after configuration.
 *
 * @param rule - The rule.
 * @param config - The loaded configuration.
 * @returns The resolved severity.
 */
function severityOf(rule: AnyRule, config: Config): Severity {
  const entry = config.rules?.[rule.id];
  const override = typeof entry === "string" ? entry : entry?.severity;
  return override ?? rule.severity ?? "error";
}

/**
 * Prints every rule with its severity and title.
 *
 * @param root - The absolute project root. Defaults to the working directory.
 * @returns The listing, one rule per line.
 */
export async function list(root: string = process.cwd()): Promise<string> {
  const { rules, config } = await loadedRules(root);
  return rules
    .slice()
    .sort((left, right) => left.id.localeCompare(right.id))
    .map(
      (rule) =>
        `${severityOf(rule, config).padEnd(5)} ${rule.id}  ${rule.title}`,
    )
    .join("\n");
}

/**
 * Prints the guideline for a rule.
 *
 * @param rule - The rule id.
 * @param root - The absolute project root. Defaults to the working directory.
 * @returns The guideline content.
 * @throws When no rule has the id.
 */
export async function explain(
  rule: string,
  root: string = process.cwd(),
): Promise<string> {
  const { rules } = await loadedRules(root);
  const found = rules.find((candidate) => candidate.id === rule);
  if (!found) {
    throw new Error(`No such rule: ${rule}`);
  }
  if (!found.docs) {
    return `${found.id}: ${found.title}\nThe rule has no guideline.`;
  }
  return readFileSync(
    module.resolve(found.docs, join(root, "package.json")),
    "utf8",
  );
}

/** The starter rule `init` writes. It works in any project. */
const STARTER_RULE = `import { defineRule, vibator } from "vibator";

export default defineRule({
