/**
 * The `git` namespace: gateway to git functionality.
 *
 * @packageDocumentation
 */
import { execFileSync } from "node:child_process";
import { requireRoot } from "../runtime.ts";

const MAX_BUFFER = 512 * 1024 * 1024;

/**
 * The git status of one path.
 */
export interface StatusEntry {
  /** The repo-relative path. */
  readonly path: string;
  /** True when the path holds staged changes. */
  readonly staged: boolean;
  /** True when the path holds unstaged changes. */
  readonly unstaged: boolean;
  /** True when git tracks the path for the first time. */
  readonly untracked: boolean;
}

/**
 * Runs a git command from the project root and returns its trimmed output.
 *
 * @param args - The arguments passed to git.
 * @returns The trimmed standard output.
 */
function output(args: string[]): string {
  return execFileSync("git", args, {
    cwd: requireRoot(),
    encoding: "utf8",
    maxBuffer: MAX_BUFFER,
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
}

/**
 * Runs a git command whose output is a NUL-separated path list.
 *
 * @param args - The arguments passed to git.
 * @returns The paths git printed.
 */
function paths(args: string[]): string[] {
  return execFileSync("git", args, {
    cwd: requireRoot(),
    encoding: "buffer",
    maxBuffer: MAX_BUFFER,
    stdio: ["ignore", "pipe", "pipe"],
  })
    .toString("utf8")
    .split("\0")
    .filter(Boolean);
}

/**
 * Gateway to git functionality.
 */
export const git = {
  /**
   * Reports whether the project root sits inside a git repository.
   *
   * @returns Whether the root sits inside a git repository.
   */
  isRepo(): boolean {
    try {
      return output(["rev-parse", "--is-inside-work-tree"]) === "true";
    } catch {
      return false;
    }
  },

  /**
   * The tracked and untracked-not-ignored paths git keeps.
   *
   * @returns The repo-relative paths.
   */
  files(): string[] {
    return paths([
      "ls-files",
      "-z",
      "--cached",
      "--others",
      "--exclude-standard",
    ]);
  },

  /**
   * The untracked paths git keeps.
   *
   * @returns The repo-relative paths.
   */
  untrackedFiles(): string[] {
    return paths(["ls-files", "-z", "--others", "--exclude-standard"]);
  },

  /**
   * The paths this working tree changed against `HEAD`, present on disk.
   *
   * @returns The repo-relative paths.
   */
  changedFiles(): string[] {
    const changed = paths([
      "diff",
      "--name-only",
      "--diff-filter=d",
      "-z",
      "HEAD",
    ]);
    return [...new Set([...changed, ...this.untrackedFiles()])];
  },

  /**
   * The paths staged for the next commit, present on disk.
   *
   * @returns The repo-relative paths.
   */
  stagedFiles(): string[] {
    return paths(["diff", "--name-only", "--cached", "--diff-filter=d", "-z"]);
  },

  /**
   * The paths this branch changed since it diverged from `base`.
   *
   * @param base - The ref to diff against.
   * @returns The repo-relative paths.
   */
  changedSince(base: string): string[] {
    if (base.startsWith("-")) {
      throw new Error(`refusing a git ref that looks like an option: ${base}`);
    }
    return paths([
      "diff",
      "--name-only",
      "--diff-filter=d",
      "-z",
      "--end-of-options",
      `${base}...HEAD`,
    ]);
  },

  /**
   * The working-tree status of the given paths.
   *
   * @param pathsToCheck - The repo-relative paths to inspect.
   * @returns One status entry per changed path.
   */
  status(pathsToCheck: string[]): StatusEntry[] {
    const report = execFileSync(
      "git",
      ["status", "--porcelain", "--", ...pathsToCheck],
      { cwd: requireRoot(), encoding: "utf8", maxBuffer: MAX_BUFFER },
    );
    return report
      .split("\n")
      .filter((line) => line.length > 0)
      .map((line) => {
        const code = line.slice(0, 2);
        return {
          path: line.slice(3),
          staged: code[0] !== " " && code[0] !== "?",
          unstaged: code[1] !== " " && code[1] !== "?",
          untracked: code === "??",
        };
      });
  },

  /**
   * Restores the given tracked paths from the index.
   *
   * @param pathsToRestore - The repo-relative paths to restore.
   */
  restore(pathsToRestore: string[]): void {
    output(["checkout", "--", ...pathsToRestore]);
  },
};

/**
 * The `glob` namespace: match paths against globs.
 *
 * @packageDocumentation
 */
import { matchesGlob } from "node:path";

/**
 * Match paths against globs, with `!` prefixes read as exclusions.
 */
export const glob = {
  /**
   * Whether a path matches the globs and none of the exclusions.
   *
   * @param path - The path to test.
   * @param globs - One glob, or several; a `!` prefix marks an exclusion.
   * @returns Whether the path is included and not excluded.
   */
  matches(path: string, globs: string | string[]): boolean {
    const list = Array.isArray(globs) ? globs : [globs];
    const includes = list.filter((glob) => !glob.startsWith("!"));
    const excludes = list
      .filter((glob) => glob.startsWith("!"))
      .map((glob) => glob.slice(1));
    const included =
      includes.length === 0 || includes.some((glob) => matchesGlob(path, glob));
    const excluded = excludes.some((glob) => matchesGlob(path, glob));
    return included && !excluded;
  },
};

/**
 * The `ignore` namespace: check ignore markers for a rule at line, node, or
 * file level.
 *
 * @remarks A marker reads `vibator-ignore <rule-id>: <reason>` on the line above
 * the finding, or `vibator-ignore-file <rule-id>: <reason>` anywhere in the
 * file. The reason is optional.
 *
 * @packageDocumentation
 */
import type { Node, SourceFile } from "typescript";
import type { File } from "../project/index.ts";
import { loadTypeScript } from "../typescript.ts";

/**
 * Whether any marker with the keyword in the text names the rule.
 *
 * @param text - The text to scan.
 * @param keyword - The marker keyword, such as `vibator-ignore`.
 * @param rule - The rule id the marker must name.
 * @returns Whether a matching marker names the rule.
 */
function markerNames(text: string, keyword: string, rule: string): boolean {
  const pattern = new RegExp(`${keyword}\\s+([^:\\n]*)`, "g");
  for (const match of text.matchAll(pattern)) {
    const ids = (match[1] ?? "")
      .split(",")
      .map((id) => id.trim())
      .filter(Boolean);
    if (ids.includes(rule)) return true;
  }
  return false;
}

/**
 * The text of a 0-based line, or undefined when out of range.
 *
 * @param sourceFile - The source file to read.
 * @param index - The 0-based line index.
 * @returns The line text, or undefined when out of range.
 */
function lineText(sourceFile: SourceFile, index: number): string | undefined {
  if (index < 0) return undefined;
  const starts = sourceFile.getLineStarts();
  if (index >= starts.length) return undefined;
  const start = starts[index] ?? 0;
  const end =
    index + 1 < starts.length ? starts[index + 1] : sourceFile.text.length;
  return sourceFile.text.slice(start, end);
}

/**
 * Whether a node is one an ignore marker can attach to.
 *
 * @param typescript - The TypeScript module.
 * @param node - The node to inspect.
 * @returns Whether the node is a scope a marker can attach to.
 */
function isScope(typescript: typeof import("typescript"), node: Node): boolean {
  return (
    typescript.isClassDeclaration(node) ||
    typescript.isFunctionDeclaration(node) ||
    typescript.isFunctionExpression(node) ||
    typescript.isArrowFunction(node) ||
    typescript.isMethodDeclaration(node) ||
    typescript.isInterfaceDeclaration(node) ||
    typescript.isEnumDeclaration(node) ||
    typescript.isModuleDeclaration(node)
  );
}

/**
 * Check whether an ignore marker silences a rule.
 */
export const ignore = {
  /**
   * Reports whether a marker on the line above names the rule.
   *
   * @param file - The file the line belongs to.
   * @param line - The 1-based line the finding sits on.
   * @param rule - The rule id the marker must name.
   * @returns Whether a marker on the line above names the rule.
   */
  line(file: File, line: number, rule: string): boolean {
    if (line < 2) return false;
    const above = file.content.split("\n")[line - 2];
    return above !== undefined && markerNames(above, "vibator-ignore", rule);
  },

  /**
   * Reports whether a marker above the node or an enclosing class, function,
   * method, interface, enum, or module names the rule.
   *
   * @param node - The node the finding sits on.
   * @param rule - The rule id the marker must name.
   * @returns Whether a marker covering the node names the rule.
   */
  node(node: Node, rule: string): boolean {
    const typescript = loadTypeScript();
    const sourceFile = node.getSourceFile();
    let current: Node | undefined = node;
    while (current) {
      if (current === node || isScope(typescript, current)) {
        const startLine = sourceFile.getLineAndCharacterOfPosition(
          current.getStart(),
        ).line;
        const above = lineText(sourceFile, startLine - 1);
        if (above !== undefined && markerNames(above, "vibator-ignore", rule)) {
          return true;
        }
      }
      current = current.parent;
    }
    return false;
  },

  /**
   * Reports whether a file-level marker names the rule.
   *
   * @param file - The file to inspect.
   * @param rule - The rule id the marker must name.
   * @returns Whether a file-level marker names the rule.
   */
  file(file: File, rule: string): boolean {
    return markerNames(file.content, "vibator-ignore-file", rule);
  },
};

/**
 * The `json` namespace: parse JSON files.
 *
 * @packageDocumentation
 */
import type { File } from "../project/index.ts";

/**
 * Flattens a value into its dotted key paths, from a prefix.
 *
 * @param value - The value to flatten.
 * @param prefix - The dotted path accumulated so far.
 * @returns The dotted key paths beneath the value.
 */
function flatten(value: unknown, prefix: string): string[] {
  if (value === null || typeof value !== "object") {
    return prefix === "" ? [] : [prefix];
  }
  return Object.entries(value).flatMap(([key, child]) => {
    const path = prefix === "" ? key : `${prefix}.${key}`;
    return flatten(child, path);
  });
}

/**
 * Parse JSON files.
 */
export const json = {
  /**
   * Parses a JSON file into its value.
   *
   * @param file - The JSON file to parse.
   * @returns The parsed value, or `undefined` when the content is not valid JSON.
   */
  parse(file: File): unknown {
    try {
      return JSON.parse(file.content);
    } catch {
      return undefined;
    }
  },

  /**
   * Flattens a value into its dotted key paths.
   *
   * @param value - The value to flatten.
   * @returns Every dotted key path.
   */
  keys(value: unknown): string[] {
    return flatten(value, "");
  },
};

/**
 * The `module` namespace: resolve references to files.
 *
 * @packageDocumentation
 */
import { createRequire } from "node:module";
import { dirname, isAbsolute, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { requireRoot } from "../runtime.ts";

/**
 * The error for a specifier that resolves as no package. A file-looking
 * specifier carries the `./` hint.
 *
 * @param specifier - The specifier that failed.
 * @param error - The resolution error.
 * @returns The error to throw.
 */
function packageError(specifier: string, error: unknown): Error {
  const message = error instanceof Error ? error.message : String(error);
  const hint = /[./]/.test(specifier)
    ? ` A project file starts with "./".`
    : "";
  return new Error(
    `Cannot find a package for "${specifier}".${hint}\n${message}`,
  );
}

/**
 * Resolve references to files.
 */
export const module = {
  /**
   * Resolves a reference to an absolute file path in this order:
   *
   * 1. An absolute path: returned as it is.
   * 2. A path starting with `.`: joined onto the directory of `from`.
   * 3. Anything else: a package specifier resolved by Node, honoring the
   *    `exports` map.
   *
   * Local paths are not checked for existence.
   *
   * @param specifier - The reference to resolve.
   * @param from - The file the resolution starts from, defaulting to the
   * root `package.json`.
   * @returns The absolute file path.
   * @throws Error When a package is not installed.
   */
  resolve(
    specifier: string,
    from: string = join(requireRoot(), "package.json"),
  ): string {
    if (isAbsolute(specifier) || specifier.startsWith(".")) {
      return resolve(dirname(from), specifier);
    }
    try {
      return createRequire(pathToFileURL(from).href).resolve(specifier);
    } catch (error) {
      throw packageError(specifier, error);
    }
  },
};

/**
 * The `package` namespace: parse and manage `package.json` files.
 *
 * @packageDocumentation
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { File } from "../project/index.ts";
import { requireRoot } from "../runtime.ts";

/**
 * A parsed `package.json`.
 */
export interface PackageManifest {
  /** The package name. */
  readonly name: string;
  /** The package version. */
  readonly version: string;
  /** The scripts, keyed by name. */
  readonly scripts: Record<string, string>;
  /** The runtime dependencies, keyed by name. */
  readonly dependencies: Record<string, string>;
  /** The development dependencies, keyed by name. */
  readonly devDependencies: Record<string, string>;
  /** The peer dependencies, keyed by name. */
  readonly peerDependencies: Record<string, string>;
}

/**
 * Coerces a value to a string map, defaulting to an empty one.
 *
 * @param value - The value to coerce.
 * @returns The value as a string map, or an empty map.
 */
function stringMap(value: unknown): Record<string, string> {
  return value !== null && typeof value === "object"
    ? (value as Record<string, string>)
    : {};
}

/**
 * Builds a manifest from `package.json` content.
 *
 * @param content - The `package.json` content.
 * @returns The parsed manifest.
 */
function toManifest(content: string): PackageManifest {
  const raw = JSON.parse(content) as Record<string, unknown>;
  return {
    name: typeof raw.name === "string" ? raw.name : "",
    version: typeof raw.version === "string" ? raw.version : "",
    scripts: stringMap(raw.scripts),
    dependencies: stringMap(raw.dependencies),
    devDependencies: stringMap(raw.devDependencies),
    peerDependencies: stringMap(raw.peerDependencies),
  };
}

/**
 * Parse and manage `package.json` files.
 *
 * @remarks Exported as `pkg` because `package` is a reserved word; it is exposed
 * on the framework namespace as `vibator.package`.
 */
export const pkg = {
  /** The parsed root `package.json`. */
  get root(): PackageManifest {
    return toManifest(
      readFileSync(join(requireRoot(), "package.json"), "utf8"),
    );
  },

  /**
   * Parses a `package.json` file into a manifest.
   *
   * @param file - The `package.json` file to parse.
   * @returns The parsed manifest.
   */
  parse(file: File): PackageManifest {
    return toManifest(file.content);
  },
};

