/**
 * The `shell` namespace: gateway to the shell.
 *
 * @packageDocumentation
 */
import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { requireRoot } from "../runtime.ts";

/**
 * The options for a shell command.
 */
export interface ShellOptions {
  /** The working directory, relative to the project root. */
  cwd?: string;
  /** The time a command runs before it is stopped, in milliseconds. */
  timeoutMs?: number;
}

/**
 * The outcome of a shell command.
 */
export interface ShellResult {
  /** True when the command exits with code 0. */
  readonly ok: boolean;
  /** The captured standard output. */
  readonly stdout: string;
  /** The captured standard error. */
  readonly stderr: string;
  /** The exit code. */
  readonly code: number;
}

/**
 * Gateway to the shell.
 */
export const shell = {
  /**
   * Runs a command and returns its outcome.
   *
   * @param command - The command to run.
   * @param options - The working directory and timeout. Defaults to the root
   * and no timeout.
   * @returns The outcome of the command.
   */
  run(command: string, options: ShellOptions = {}): ShellResult {
    const root = requireRoot();
    const result = spawnSync(command, {
      cwd: options.cwd ? join(root, options.cwd) : root,
      timeout: options.timeoutMs,
      encoding: "utf8",
      shell: true,
    });
    return {
      ok: result.status === 0,
      stdout: result.stdout ?? "",
      stderr: result.stderr ?? "",
      code: result.status ?? 1,
    };
  },
};

/**
 * The `text` namespace: parse and manipulate files as plain text.
 *
 * @packageDocumentation
 */
import type { File, FileSet } from "../project/index.ts";

/**
 * One line of text with its number.
 */
export interface Line {
  /** The 1-based line number. */
  readonly number: number;
  /** The line content. */
  readonly text: string;
}

/**
 * A line and column in a file.
 */
export interface Position {
  /** The 1-based line. */
  readonly line: number;
  /** The 1-based column. */
  readonly column: number;
}

/**
 * One match of a pattern with its position.
 */
export interface Match {
  /** The matched text. */
  readonly text: string;
  /** The character offset of the match. */
  readonly index: number;
  /** The 1-based line the match starts on. */
  readonly line: number;
  /** The 1-based column the match starts on. */
  readonly column: number;
  /** The captured groups. */
  readonly groups: string[];
}

/**
 * One match of a pattern in a file of a set, with the file's path.
 */
export interface Hit extends Match {
  /** The absolute path of the file the match is in. */
  readonly file: string;
}

/**
 * Resolves a character offset to a 1-based line and column.
 *
 * @param content - The text the offset points into.
 * @param offset - The character offset.
 * @returns The 1-based line and column.
 */
function resolvePosition(content: string, offset: number): Position {
  const clamped = Math.max(0, Math.min(offset, content.length));
  let line = 1;
  let lineStart = 0;
  for (let index = 0; index < clamped; index += 1) {
    if (content[index] === "\n") {
      line += 1;
      lineStart = index + 1;
    }
  }
  return { line, column: clamped - lineStart + 1 };
}

/**
 * Replaces every non-newline character with a space, keeping line positions.
 *
 * @param region - The text region to blank.
 * @returns The region with non-newline characters replaced by spaces.
 */
function mask(region: string): string {
  return region.replace(/[^\n]/g, " ");
}

/**
 * Parse and manipulate files as plain text.
 */
export const text = {
  /**
   * Splits a file into numbered lines.
   *
   * @param file - The file to split.
   * @returns The numbered lines.
   */
  lines(file: File): Line[] {
    if (file.content === "") return [];
    const split = file.content.split("\n");
    if (split.length > 1 && split[split.length - 1] === "") split.pop();
    return split.map((line, index) => ({ number: index + 1, text: line }));
  },

  /**
   * Returns the file content with JavaScript and TypeScript comments blanked,
   * keeping line positions.
   *
   * @param file - The file to mask.
   * @returns The content with comments blanked.
   */
  maskComments(file: File): string {
    return file.content
      .replace(/\/\*(?:[^*]|\*(?!\/))*\*\//g, mask)
      .replace(/\/\/[^\n]*/g, mask);
  },

  /**
   * Returns the file content with Markdown code fences and spans blanked,
   * keeping line positions.
   *
   * @param file - The file to mask.
   * @returns The content with code regions blanked.
   */
  maskCode(file: File): string {
    return file.content
      .replace(/```[\s\S]*?```/g, mask)
      .replace(/`[^`\n]*`/g, mask);
  },

  /**
   * Resolves a character offset to a line and column.
   *
   * @param file - The file the offset points into.
   * @param offset - The character offset.
   * @returns The line and column.
   */
  positionAt(file: File, offset: number): Position {
    return resolvePosition(file.content, offset);
  },

  /**
   * Returns every match of a pattern across a set of files, each with the
   * path of its file. A hit spreads into a diagnostic as it is.
   *
   * @param files - The files to search.
   * @param pattern - The pattern to match.
   * @returns Every match, in file order.
   */
  search(files: FileSet, pattern: RegExp): Hit[] {
    return files.flatMap((file) =>
      text
        .matches(file, pattern)
        .map((match) => ({ file: file.path, ...match })),
    );
  },

  /**
   * Returns every match of a pattern with its position.
   *
   * @param file - The file to search.
   * @param pattern - The pattern to match.
   * @returns Every match with its position.
   */
  matches(file: File, pattern: RegExp): Match[] {
    const global = pattern.global
      ? pattern
      : new RegExp(pattern.source, `${pattern.flags}g`);
    const found: Match[] = [];
    for (const match of file.content.matchAll(global)) {
      const index = match.index ?? 0;
      const position = resolvePosition(file.content, index);
      found.push({
        text: match[0],
        index,
        line: position.line,
        column: position.column,
        groups: match.slice(1) as string[],
      });
    }
    return found;
  },

  /**
   * Reports whether the file content is binary.
   *
   * @param file - The file to inspect.
   * @returns Whether the content is binary.
   */
  binary(file: File): boolean {
    return file.bytes.includes(0);
  },
};

/**
 * The `ts` namespace: parse and manipulate TypeScript files.
 *
 * @packageDocumentation
 */
import { dirname } from "node:path";
import type { Node, SourceFile, TypeChecker } from "typescript";
import { type File, FileSet } from "../project/index.ts";
import { requireRoot } from "../runtime.ts";
import { loadTypeScript } from "../typescript.ts";

/**
 * One node in a syntax tree with its position.
 */
export interface NodeCursor {
  /** The TypeScript node. */
  readonly node: Node;
  /** The 1-based line the node starts on. */
  readonly line: number;
}

/**
 * The syntax tree of a parsed file.
 */
export interface Ast {
  /** The TypeScript source file. */
  readonly source: SourceFile;
  /** Every node, flattened in source order. */
  readonly nodes: NodeCursor[];
  /**
   * The 1-based line a character offset falls on.
   *
   * @param offset - A character offset into the file.
   * @returns The 1-based line.
   */
  lineAt(offset: number): number;
}

/**
 * A type-checked TypeScript program.
 */
export interface Program {
  /** The program type checker. */
  readonly checker: TypeChecker;
  /** The files included in the program. */
  readonly files: FileSet;
  /**
   * The syntax tree of a file in the program.
   *
   * @param file - A file included in the program.
   * @returns The file's syntax tree.
   */
  ast(file: File): Ast;
}

/**
 * The script kind a file extension implies.
 *
 * @param typescript - The TypeScript module.
 * @param ext - The file extension, including the dot.
 * @returns The script kind for that extension.
 */
function scriptKindFor(
  typescript: typeof import("typescript"),
  ext: string,
): number {
  if (ext === ".tsx") return typescript.ScriptKind.TSX;
  if (ext === ".jsx") return typescript.ScriptKind.JSX;
  if (ext === ".js" || ext === ".mjs" || ext === ".cjs") {
    return typescript.ScriptKind.JS;
  }
  return typescript.ScriptKind.TS;
}

/**
 * Builds an Ast from a source file.
 *
 * @param typescript - The TypeScript module.
 * @param source - The source file to walk.
 * @returns The syntax tree.
 */
function astFromSource(
  typescript: typeof import("typescript"),
  source: SourceFile,
): Ast {
  const nodes: NodeCursor[] = [];
  const visit = (node: Node): void => {
    nodes.push({
      node,
      line:
        source.getLineAndCharacterOfPosition(node.getStart(source)).line + 1,
    });
    typescript.forEachChild(node, visit);
  };
  typescript.forEachChild(source, visit);
  return {
    source,
    nodes,
    lineAt: (offset: number): number =>
      source.getLineAndCharacterOfPosition(offset).line + 1,
  };
}

/**
 * Parse and manipulate TypeScript files.
 */
export const ts = {
  /**
   * Parses a TypeScript or JavaScript file into a syntax tree.
   *
   * @param file - The file to parse.
   * @returns The file's syntax tree.
   */
  parse(file: File): Ast {
    const typescript = loadTypeScript();
    const source = typescript.createSourceFile(
      file.name,
      file.content,
      typescript.ScriptTarget.Latest,
      true,
      scriptKindFor(typescript, file.ext),
    );
    return astFromSource(typescript, source);
  },

  /**
   * Builds a type-checked program from a `tsconfig` file.
   *
   * @param tsconfig - The `tsconfig` file the program resolves against.
   * @returns The type-checked program.
   */
  program(tsconfig: File): Program {
    const typescript = loadTypeScript();
    const config = typescript.readConfigFile(
      tsconfig.path,
      typescript.sys.readFile,
    );
    const parsed = typescript.parseJsonConfigFileContent(
      config.config,
      typescript.sys,
      dirname(tsconfig.path),
    );
    const program = typescript.createProgram(parsed.fileNames, parsed.options);
    const projectFiles = parsed.fileNames.filter(
      (name) => !name.endsWith(".d.ts"),
    );
    return {
      checker: program.getTypeChecker(),
      files: new FileSet(requireRoot(), projectFiles),
      ast(file: File): Ast {
        const source = program.getSourceFile(file.path);
        if (!source) {
          throw new Error(`file not in program: ${file.path}`);
        }
        return astFromSource(typescript, source);
      },
    };
  },
};

# From script to rule

This guide turns a check script into a vibator rule. The script checks that
every environment variable the code reads is listed in `.env.example`.

## The script

```js
// scripts/check-env-example.mjs
import { globSync, readFileSync } from "node:fs";

const documented = new Set(
  readFileSync(".env.example", "utf8")
    .split("\n")
    .map((line) => line.split("=")[0].trim()),
);

let failed = false;
for (const path of globSync("src/**/*.ts")) {
  const content = readFileSync(path, "utf8");
  for (const match of content.matchAll(/process\.env\.([A-Z0-9_]+)/g)) {
    if (!documented.has(match[1])) {
      console.error(`${path}: ${match[1]} is not in .env.example`);
      failed = true;
    }
  }
}
process.exit(failed ? 1 : 0);
```

It runs from an npm script such as
`"check:env": "node scripts/check-env-example.mjs"`.

## The rule

```ts
// .vibator/env-example.ts
import { defineRule, vibator } from "vibator";

export default defineRule({
  id: "env-example",
  title: "Every environment variable the code reads is in .env.example",
  check() {
    const example = vibator.project.files.get(`${vibator.project.root}/.env.example`);
    const documented = new Set(
      vibator.text.lines(example).map((line) => line.text.split("=")[0].trim()),
    );
    return vibator.text
      .search(vibator.project.files.match("src/**/*.ts"), /process\.env\.([A-Z0-9_]+)/)
      .filter((hit) => !documented.has(hit.groups[0]))
      .map((hit) => ({
        ...hit,
        message: `${hit.groups[0]} is read but not in .env.example`,
        expected: "Every variable the code reads has an entry in .env.example",
        fix: `Add ${hit.groups[0]}= to .env.example`,
      }));
  },
});
```

## What changed

| In the script                | In the rule                                     |
| ---------------------------- | ----------------------------------------------- |
| `globSync("src/**/*.ts")`    | `vibator.project.files.match("src/**/*.ts")`    |
| `readFileSync(path, "utf8")` | `vibator.text.lines(file)`, or `file.content`   |
| `content.matchAll(pattern)`  | `vibator.text.search(files, pattern)`           |
| `console.error(...)`         | A finding with `message`, `expected`, and `fix` |
| `process.exit(1)`            | The rule severity, `error` by default           |
| An npm script per check      | `npx vibator` for every rule                    |

The rule also gets the shared command line options. `--staged`, `--changed`,
and `--since` limit the files in `vibator.project.files`. `--reporter` selects
pretty, JSON, or SARIF output.

## Steps

1. Write the rule in `.vibator/`.
2. Run it alone with `npx vibator --only env-example` and compare its findings
   with the script output.
3. Delete the script, its npm script, and its CI step.

## Add a guideline

When the standard needs more than its title, point `docs` at a Markdown file.
`npx vibator explain env-example` prints it.

```ts
docs: ".vibator/docs/env-example.md",
```

```md
# env-example

Every environment variable the code reads through `process.env` has an entry in
`.env.example`. Contributors copy `.env.example` to `.env`, so a missing entry
leaves the variable unset.
```

